use core::fmt;

/// Any error generated by a PacketConn.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum Error {
	Undefined,
	Encode,
	Decode,
	Closed,
	Timeout,
	BadMessage,
	EmptyMessage,
	OversizedMessage,
	UnrecognizedMessage,
	PeerNotFound,
	BadAddress,
	BadKey,
}

impl Error {
	/// The name Ironwood's Go implementation uses for this error.
	pub fn name(self) -> &'static str {
		match self {
			Error::Undefined => "ErrUndefined",
			Error::Encode => "ErrEncode",
			Error::Decode => "ErrDecode",
			Error::Closed => "ErrClosed",
			Error::Timeout => "ErrTimeout",
			Error::BadMessage => "ErrBadMessage",
			Error::EmptyMessage => "ErrEmptyMessage",
			Error::OversizedMessage => "ErrOversizedMessage",
			Error::UnrecognizedMessage => "ErrUnrecognizedMessage",
			Error::PeerNotFound => "ErrPeerNotFound",
			Error::BadAddress => "ErrBadAddress",
			Error::BadKey => "ErrBadKey",
		}
	}
}

impl fmt::Display for Error {
	fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
		f.write_str(self.name())
	}
}

impl core::error::Error for Error {}
